<script setup lang="ts">
import { computed,ref } from "vue"; import {useRouter} from "vue-router";
import AppShell from "@/components/zs/AppShell.vue"; import PageHeader from "@/components/zs/PageHeader.vue"; import Panel from "@/components/zs/Panel.vue"; import DataTable from "@/components/zs/DataTable.vue"; import Toolbar from "@/components/zs/Toolbar.vue"; import SearchInput from "@/components/zs/SearchInput.vue"; import StatusBadge from "@/components/zs/StatusBadge.vue"; import ZButton from "@/components/zs/ZButton.vue"; import ScoreBadge from "@/components/crm/ScoreBadge.vue"; import Pagination from "@/components/crm/Pagination.vue"; import AsyncSection from "@/components/zs/AsyncSection.vue";
import {useCrmData} from "@/composables/useCrmData"; import {useAsyncData} from "@/composables/useAsyncData"; import {crmRepository} from "@/services/crm/repository"; import {setPageMeta} from "@/lib/page-meta";
setPageMeta("Leads","Qualified pipeline with lead intelligence and outreach actions.");const data=useCrmData(),router=useRouter(),search=ref(""),status=ref("All statuses"),ownerId=ref(""),page=ref(1);const listing=useAsyncData(()=>crmRepository.leadsPage(data.activeCompanyId.value,{search:search.value,status:status.value==="All statuses"?undefined:status.value,owner_id:ownerId.value||undefined,page:page.value,per_page:10}),{watch:[data.activeCompanyId,search,status,ownerId,page]});const rows=computed(()=>listing.data.value?.data??[]);const columns=[{key:"name",header:"Lead"},{key:"company",header:"Company"},{key:"title",header:"Job title"},{key:"email",header:"Email"},{key:"source",header:"Source"},{key:"stage",header:"Status"},{key:"total",header:"Score"},{key:"owner",header:"Owner"},{key:"lastActivity",header:"Last activity"},{key:"actions",header:"",align:"right" as const}];
</script>
<template><AppShell><PageHeader title="Leads" :description="`${listing.data.value?.total??0} leads in the active company`"><template #actions><ZButton @click="router.push('/crm/capture')">Add or import</ZButton><ZButton variant="outline" @click="router.push('/crm/pipeline')">View pipeline</ZButton></template></PageHeader><Panel><Toolbar><SearchInput v-model="search" placeholder="Search lead, company, email or phone"/><select v-model="status" class="field max-w-44"><option>All statuses</option><option v-for="value in ['NEW','CONTACTED','QUALIFIED','UNQUALIFIED','CONVERTED','LOST']" :key="value">{{value}}</option></select><select v-model="ownerId" class="field max-w-44"><option value="">All owners</option><option v-for="owner in data.owners.data.value??[]" :key="owner.id" :value="owner.id">{{owner.name}}</option></select></Toolbar><AsyncSection :loading="listing.loading.value" :error="listing.error.value" :empty="listing.data.value?.total===0" @retry="listing.refresh"><DataTable :columns="columns" :rows="rows" :min-width="1350"><template #name="{row}"><button class="font-medium text-primary hover:underline" @click="router.push(`/crm/leads/${row.id}`)">{{row.name}}</button></template><template #stage="{row}"><StatusBadge :status="row.status"/></template><template #total="{row}"><ScoreBadge :score="row.score.total"/></template><template #actions="{row}"><div class="flex justify-end gap-1"><ZButton variant="ghost" @click="router.push(`/crm/leads/${row.id}`)">View</ZButton><ZButton variant="ghost" @click="router.push({path:'/outreach/compose',query:{lead:row.id}})">Outreach</ZButton></div></template><template #footer><Pagination :page="listing.data.value?.currentPage??1" :pages="listing.data.value?.lastPage??1" :total="listing.data.value?.total??0" @change="page=$event"/></template></DataTable></AsyncSection></Panel></AppShell></template>
